head.b:skin:
/*
<Group description="ARABIA PRO X — Colors" selector="body">
<Variable name="keycolor" description="Primary blue" type="color" default="#1264d8" value="#1264d8"/>
<Variable name="accentcolor" description="Secondary turquoise" type="color" default="#087f8c" value="#087f8c"/>
<Variable name="backgroundcolor" description="Page background" type="color" default="#f7f9fc" value="#f7f9fc"/>
</Group>
*/
/* ARABIA PRO X 2026 — original editorial system. */
:root{--blue:$(keycolor);--turquoise:$(accentcolor);--surface:#fff;--bg:$(backgroundcolor);--ink:#14243a;--muted:#526278;--line:#e1e7ef;--amber:#ffb547;--radius:18px;--shadow:0 12px 38px #14243a08;--reading-size:19px;--header-height:76px;color-scheme:light}
html[data-theme=dark]{--surface:#152237;--bg:#0c1625;--ink:#edf3fc;--muted:#aabbd0;--line:#2c3e54;--blue:#78b0ff;--turquoise:#58d8df;--shadow:0 12px 38px #0002;color-scheme:dark}
@media(prefers-color-scheme:dark){html:not([data-theme=light]){--surface:#152237;--bg:#0c1625;--ink:#edf3fc;--muted:#aabbd0;--line:#2c3e54;--blue:#78b0ff;--turquoise:#58d8df;--shadow:0 12px 38px #0002;color-scheme:dark}}
*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:100px}body{margin:0;background:var(--bg);color:var(--ink);font-family:Tajawal,"IBM Plex Sans Arabic",system-ui,sans-serif;font-size:16px;line-height:1.65;overflow-wrap:anywhere}body.scroll-lock{overflow:hidden}a{color:inherit;text-decoration:none}button,input,select{font:inherit}button,a,input,select,summary{-webkit-tap-highlight-color:transparent}button,summary{cursor:pointer}button{color:inherit}button:disabled{cursor:wait;opacity:.6}img,svg,video,iframe{max-width:100%}img{height:auto;display:block}svg.icon{width:21px;height:21px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round;flex:none}button{background:none;border:0}a:hover{color:var(--blue)}:focus-visible{outline:3px solid var(--blue);outline-offset:4px;border-radius:4px}[hidden]{display:none!important}.shell{width:min(1280px,calc(100% - 48px));margin-inline:auto}.skip-link{position:fixed;inset-block-start:8px;inset-inline-start:16px;transform:translateY(-160%);background:var(--ink);color:var(--surface);padding:12px 20px;z-index:100}.skip-link:focus{transform:none}.sr-only{position:absolute;width:1px;height:1px;padding:0;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}.icon-button{width:44px;height:44px;display:inline-flex;align-items:center;justify-content:center;border-radius:12px;flex:none}.icon-button:hover{background:var(--bg);color:var(--blue)}.eyebrow{font-size:12px;font-weight:800;color:var(--turquoise);letter-spacing:.03em}.pill{display:inline-flex;align-items:center;gap:6px;font-size:12px;font-weight:700;background:var(--bg);color:var(--blue);border:1px solid var(--line);border-radius:7px;padding:3px 9px}.button{min-height:44px;display:inline-flex;align-items:center;justify-content:center;gap:8px;border:1px solid var(--line);padding:9px 16px;border-radius:11px;background:var(--surface);font-weight:700}.button:hover{border-color:var(--blue);color:var(--blue)}.button.primary{background:var(--blue);color:var(--surface);border-color:transparent}html[data-theme=dark] .button.primary{color:#0c1625}.status-message{color:var(--muted);font-size:14px;line-height:1.7}.section-heading{display:flex;align-items:center;justify-content:space-between;gap:16px;margin:0 0 20px}.section-heading h2,.section-heading h1{margin:0;font-size:24px;line-height:1.35;letter-spacing:-.025em}.section-heading h2:before{content:"";display:inline-block;width:5px;height:21px;background:var(--blue);margin-inline-end:10px;vertical-align:middle;border-radius:6px}.section-heading a{font-size:13px;font-weight:700;color:var(--muted);white-space:nowrap}.site-header{position:sticky;inset-block-start:0;z-index:40;background:var(--surface);border-bottom:1px solid var(--line)}.header-inner{display:flex;align-items:center;gap:24px;min-height:var(--header-height)}.brand{display:flex;align-items:center;gap:12px;flex:none}.brand-mark{width:40px;height:40px;background:var(--blue);color:var(--surface);border-radius:13px;display:grid;place-items:center;transform:rotate(-6deg)}.brand-mark svg{transform:rotate(6deg)}.brand-title{font-size:23px;font-weight:800;line-height:1.1;letter-spacing:-.04em}.brand-caption{font-size:10px;letter-spacing:.16em;color:var(--muted);display:block;line-height:1.5;margin-top:4px}.brand-image{max-width:180px;max-height:48px;width:auto}.header-actions{display:flex;gap:3px;margin-inline-start:auto;align-items:center}.primary-nav{min-width:0;display:flex;align-items:center;gap:20px;font-weight:700;font-size:14px}.primary-nav .widget-content,.primary-nav ul{display:flex;align-items:center;gap:20px}.primary-nav ul{list-style:none;padding:0;margin:0;flex-wrap:wrap}.primary-nav a[aria-current=page]{color:var(--blue)}.menu-toggle{display:none}.explore{position:relative;flex:none}.explore>summary{min-height:44px;display:flex;gap:7px;align-items:center;font-size:14px;font-weight:700;list-style:none}.explore>summary::-webkit-details-marker{display:none}.explore[open]>summary{color:var(--blue)}.explore-panel{position:absolute;inset-block-start:calc(100% + 17px);inset-inline-end:0;width:min(500px,80vw);padding:24px;background:var(--surface);border:1px solid var(--line);border-radius:16px;box-shadow:var(--shadow)}.label-links{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}.label-links a{padding:10px;background:var(--bg);border-radius:8px;font-size:13px}.label-links small{color:var(--muted);margin-inline-start:5px}.drawer-backdrop{display:none}.announcement .widget-content{padding:10px 0;font-size:14px}.breaking{display:flex;align-items:center;gap:18px;margin-block:20px;background:var(--surface);border:1px solid var(--line);border-radius:12px;padding:10px 16px;min-height:46px}.breaking-label{display:flex;align-items:center;gap:9px;color:var(--blue);font-size:13px;font-weight:800;white-space:nowrap}.breaking-label:before{content:"";width:7px;height:7px;border-radius:50%;background:var(--blue)}.breaking-headlines{display:flex;gap:28px;overflow:auto;scrollbar-width:thin;flex:1;min-width:0;font-size:13px}.breaking-headlines a{white-space:nowrap;padding-block:3px}.page-layout{display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:36px;padding-block:30px 48px;align-items:start}.main-column{min-width:0}.sidebar{display:flex;flex-direction:column;gap:24px;min-width:0}.sidebar .widget{border:1px solid var(--line);background:var(--surface);padding:22px;border-radius:var(--radius);margin:0}.sidebar h2{font-size:18px;margin:0 0 18px}.sidebar .label-links{grid-template-columns:repeat(2,minmax(0,1fr))}.popular-list{list-style:none;padding:0;margin:0;counter-reset:popular}.popular-list li{counter-increment:popular;display:flex;gap:12px;padding:14px 0;border-bottom:1px solid var(--line)}.popular-list li:last-child{border:0;padding-bottom:0}.popular-list li:before{min-width:2ch;white-space:nowrap;flex:none;content:counter(popular,decimal-leading-zero);font:700 24px/1.3 system-ui,sans-serif;color:var(--blue);opacity:.8}.popular-list a{font-size:15px;line-height:1.55;font-weight:700}.popular-list img{width:64px;height:64px;object-fit:cover;border-radius:9px;margin-block-end:8px}.editorial-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24px}.story{min-width:0}.story-media{display:block;aspect-ratio:16/10;overflow:hidden;background:var(--line);border-radius:var(--radius);position:relative}.story-media img{width:100%;height:100%;object-fit:cover;transition:transform .35s}.story-media:hover img{transform:scale(1.035)}.no-image{display:grid;place-items:center;color:var(--muted);background:var(--surface);border:1px solid var(--line)}.no-image svg{width:38px;height:38px;opacity:.5}.story-copy{padding-block-start:14px}.story h2,.story h3{font-size:21px;line-height:1.5;margin:9px 0;font-weight:800;letter-spacing:-.025em}.story-summary{font-size:14px;color:var(--muted);margin:10px 0 0;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}.story-meta{display:flex;align-items:center;gap:9px;flex-wrap:wrap;font-size:12px;color:var(--muted)}.editorial-grid>.story:first-child{grid-column:1/-1;display:grid;grid-template-columns:1.2fr 1fr;gap:26px;align-items:center;padding-block-end:24px;border-bottom:1px solid var(--line)}.editorial-grid>.story:first-child h2{font-size:30px;line-height:1.45}.editorial-grid>.story:first-child .story-copy{padding:0}.editorial-grid>.story:nth-child(n+4){display:grid;grid-template-columns:100px minmax(0,1fr);gap:15px;border-top:1px solid var(--line);padding-top:18px;align-items:start}.editorial-grid>.story:nth-child(n+4) .story-media{aspect-ratio:1;border-radius:12px}.editorial-grid>.story:nth-child(n+4) .story-copy{padding:0}.editorial-grid>.story:nth-child(n+4) h2{font-size:16px;margin-block:6px}.editorial-grid>.story:nth-child(n+4) .story-summary{display:none}.module{margin-block:38px}.module-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}.module-grid .story h3{font-size:17px}.module[data-layout=lead] .module-grid{grid-template-columns:1.3fr 1fr}.module[data-layout=lead] .story:first-child{grid-row:span 3}.module[data-layout=lead] .story:not(:first-child){display:grid;grid-template-columns:78px 1fr;gap:12px;border-bottom:1px solid var(--line);padding-bottom:14px}.module[data-layout=lead] .story:not(:first-child) .story-media{aspect-ratio:1;border-radius:10px}.module[data-layout=lead] .story:not(:first-child) .story-copy{padding:0}.module[data-layout=lead] .story:not(:first-child) h3{font-size:15px;margin-top:4px}.module[data-layout=rows] .module-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.module[data-layout=rows] .story{display:grid;grid-template-columns:85px 1fr;gap:14px;padding-bottom:16px;border-bottom:1px solid var(--line)}.module[data-layout=rows] .story-media{aspect-ratio:1;border-radius:10px}.module[data-layout=rows] .story-copy{padding:0}.module[data-layout=rows] h3{font-size:16px;margin:0 0 6px}.pagination{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;margin-top:32px;padding-top:24px;border-top:1px solid var(--line)}.archive-heading{margin-bottom:25px;padding:20px;background:var(--surface);border:1px solid var(--line);border-radius:14px}.archive-heading h1{font-size:24px;margin:0}.post{background:var(--surface);border:1px solid var(--line);border-radius:22px;padding:36px;position:relative}.breadcrumbs{display:flex;align-items:center;gap:8px;font-size:12px;color:var(--muted);flex-wrap:wrap;margin-bottom:20px}.post-title{font-size:clamp(27px,3.1vw,42px);line-height:1.5;letter-spacing:-.035em;margin:14px 0 20px;font-weight:800}.post-meta{display:flex;gap:12px;align-items:center;flex-wrap:wrap;font-size:13px;color:var(--muted);padding-bottom:24px;border-bottom:1px solid var(--line)}.post-meta .author-name{font-weight:700;color:var(--ink)}.reading-tools{display:flex;gap:7px;flex-wrap:wrap;margin-block:18px}.reading-tools button{font-size:13px;min-height:44px}.post-body{font-size:var(--reading-size);line-height:1.95;margin-inline:auto;max-width:70ch;min-width:0}.post-body h2{font-size:1.45em;line-height:1.55;margin-block:1.8em .7em;scroll-margin-top:100px}.post-body h3{font-size:1.2em;line-height:1.6;margin-block:1.5em .6em}.post-body p{margin-block:0 1.2em}.post-body a{color:var(--blue);text-decoration:underline;text-underline-offset:4px}.post-body img{height:auto;border-radius:12px;max-width:100%;margin:24px auto;cursor:zoom-in}.post-body .separator{max-width:100%;clear:both}.post-body .separator a{max-width:100%;display:inline-block}.post-body blockquote{margin:28px 0;padding:20px 25px;border-inline-start:4px solid var(--turquoise);background:var(--bg);border-radius:12px;font-size:1.08em}.post-body pre{direction:ltr;text-align:left;overflow:auto;background:var(--bg);padding:20px;border:1px solid var(--line);border-radius:12px;font:14px/1.8 ui-monospace,monospace}.post-body :not(pre)>code{font-size:.85em;background:var(--bg);padding:2px 5px;border-radius:4px}.table-scroll{overflow-x:auto;max-width:100%;border:1px solid var(--line);border-radius:12px;margin-block:24px}.post-body table{width:100%;border-collapse:collapse;font-size:.85em;min-width:420px}.post-body th,.post-body td{padding:12px;border:1px solid var(--line);text-align:start}.post-body th{background:var(--bg)}.post-body iframe,.post-body video{max-width:100%}.post-body iframe[src*="youtube"],.post-body iframe[src*="vimeo"]{width:100%;height:auto;aspect-ratio:16/9}.toc{background:var(--bg);border:1px solid var(--line);border-radius:14px;padding:16px 20px;margin-block:22px;font-size:15px}.toc summary{font-weight:800;min-height:30px}.toc ol{padding-inline-start:24px;margin-block:12px 0}.toc li{margin-block:7px}.toc li.sub{margin-inline-start:18px;font-size:14px}.author-box{border-top:1px solid var(--line);margin-top:32px;padding-top:24px;display:flex;gap:14px;align-items:flex-start}.author-avatar{width:48px;height:48px;object-fit:cover;border-radius:50%}.author-box p{margin:4px 0;color:var(--muted);font-size:14px}.share-tools{display:flex;gap:8px;flex-wrap:wrap;margin-block:24px}.share-tools a,.share-tools button{font-size:13px}.comments{margin-top:32px;padding-top:24px;border-top:1px solid var(--line)}.comments h2{font-size:22px}.comment-list{list-style:none;margin:0;padding:0}.comment-list li{padding:18px 0;border-bottom:1px solid var(--line)}.comment-list time{font-size:12px;color:var(--muted)}.comment-body{font-size:15px;line-height:1.8}.comment-frame{width:100%;height:480px;border:0;display:block;margin-top:18px}.reading-progress{height:3px;background:var(--blue);position:fixed;inset-block-start:0;inset-inline-start:0;width:0;z-index:60;pointer-events:none}.to-top{position:fixed;inset-inline-end:24px;inset-block-end:24px;background:var(--surface);border:1px solid var(--line);box-shadow:var(--shadow);z-index:25}.site-footer{background:var(--surface);border-top:1px solid var(--line);padding-block:40px 25px}.footer-inner{display:grid;grid-template-columns:1.3fr 2fr;gap:40px}.footer-about p{font-size:14px;color:var(--muted);max-width:340px}.footer-links ul{list-style:none;display:flex;flex-wrap:wrap;gap:16px 25px;padding:0}.footer-links h2{font-size:16px}.footer-links a{font-size:14px}.footer-bottom{margin-top:30px;padding-top:20px;border-top:1px solid var(--line);display:flex;justify-content:space-between;flex-wrap:wrap;gap:12px;font-size:12px;color:var(--muted)}.not-found{padding:55px 25px;text-align:center;background:var(--surface);border:1px solid var(--line);border-radius:18px}.not-found strong{font:800 72px/1.2 system-ui;color:var(--blue)}.not-found h1{font-size:27px}.not-found p{color:var(--muted)}.search-dialog,.lightbox{border:1px solid var(--line);border-radius:20px;background:var(--surface);color:var(--ink);width:min(620px,calc(100% - 32px));padding:28px;max-height:85dvh}.search-dialog::backdrop,.lightbox::backdrop{background:#061326b8;backdrop-filter:blur(5px)}.dialog-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:18px}.dialog-head h2{margin:0;font-size:22px}.search-form{display:flex;gap:9px}.search-form input{width:100%;min-width:0;background:var(--bg);border:1px solid var(--line);border-radius:10px;padding:12px;color:var(--ink)}.lightbox{width:min(1100px,calc(100% - 24px));text-align:center}.lightbox img{max-height:65dvh;width:auto;margin:auto;object-fit:contain}.lightbox p{font-size:14px;color:var(--muted)}.toast{position:fixed;inset-block-end:25px;inset-inline-start:50%;transform:translateX(50%);padding:12px 20px;background:var(--ink);color:var(--surface);border-radius:12px;z-index:100;max-width:calc(100% - 32px);box-shadow:var(--shadow);font-size:14px}.arx-ad{display:flex;align-items:center;flex-direction:column;gap:8px;min-height:130px;padding:18px;margin-block:28px;border:1px solid var(--line);border-radius:12px;background:var(--surface)}.arx-ad .ad-label{font-size:11px;letter-spacing:.02em;color:var(--muted)}.arx-ad ins{display:block;width:100%;min-height:90px}.sidebar .arx-ad{min-height:280px;margin-block:0}.sidebar .arx-ad ins{min-height:250px}.ad-staging{display:none}.fixture-center{border:1px solid var(--line);border-radius:var(--radius);background:var(--surface);margin-block:24px;overflow:clip}.fixture-head{padding:20px 22px;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;gap:14px;align-items:center}.fixture-head h2{font-size:21px;margin:2px 0 0}.fixture-source{font-size:11px;color:var(--muted);margin:0}.fixture-controls{padding:15px 22px;display:flex;gap:12px;flex-wrap:wrap;border-bottom:1px solid var(--line);align-items:end}.fixture-controls label{display:grid;gap:4px;font-size:11px;color:var(--muted);flex:1;min-width:125px}.fixture-controls select,.fixture-controls input{height:42px;border:1px solid var(--line);background:var(--bg);color:var(--ink);padding:7px;border-radius:8px;width:100%;min-width:0}.fixture-tabs{display:flex;gap:5px;padding:10px 22px;overflow:auto}.fixture-tabs button{min-height:42px;padding:8px 14px;border-radius:8px;white-space:nowrap;font-size:13px}.fixture-tabs button[aria-pressed=true]{color:var(--blue);background:var(--bg);font-weight:800}.fixture-league{font-size:12px;color:var(--muted);background:var(--bg);padding:7px 22px;display:flex;align-items:center;gap:8px}.fixture-league img{width:20px;height:20px;object-fit:contain}.fixture-row{padding:15px 20px;border-bottom:1px solid var(--line);display:grid;grid-template-columns:minmax(0,1fr) 100px minmax(0,1fr) 38px;gap:12px;align-items:center}.fixture-team{display:flex;gap:9px;align-items:center;font-size:14px;font-weight:700;min-width:0}.fixture-team.away{flex-direction:row-reverse;text-align:end}.fixture-team img{height:28px;width:28px;object-fit:contain;flex:none}.fixture-score{text-align:center;font-family:system-ui,sans-serif;font-size:19px;font-weight:800;direction:ltr}.fixture-status{font-family:Tajawal,system-ui,sans-serif;font-size:11px;font-weight:500;direction:rtl;color:var(--muted);display:block}.fixture-status.live{color:var(--turquoise);font-weight:800}.fixture-note{font-size:10px;color:var(--muted);display:block;direction:rtl}.favorite-match{font-size:22px;color:var(--muted);min-width:38px;min-height:44px;border-radius:8px}.favorite-match[aria-pressed=true]{color:var(--blue)}.fixture-bottom{display:flex;justify-content:space-between;gap:15px;align-items:center;flex-wrap:wrap;padding:12px 22px;font-size:11px;color:var(--muted)}.fixture-error{padding:12px 22px;color:var(--muted);font-size:13px}.fixture-empty{padding:28px 22px;text-align:center;color:var(--muted);font-size:14px}.fixture-center.compact .fixture-controls,.fixture-center.compact .fixture-tabs,.fixture-center.compact .favorite-match{display:none}.fixture-center.compact .fixture-list{display:grid;grid-template-columns:repeat(3,minmax(0,1fr))}.fixture-center.compact .fixture-league{display:none}.fixture-center.compact .fixture-row{grid-template-columns:minmax(0,1fr) 60px minmax(0,1fr);gap:6px;border-inline-end:1px solid var(--line);padding:15px 12px}.fixture-center.compact .fixture-team{font-size:12px;flex-direction:column;text-align:center;gap:5px}.fixture-center.compact .fixture-team img{width:23px;height:23px}.fixture-center.compact .fixture-score{font-size:16px}.fixture-center.compact .fixture-head{padding:12px 18px}.fixture-center.compact .fixture-head h2{font-size:17px}.fixture-center.compact .fixture-note{display:none}.fixture-center.compact .fixture-bottom{padding:8px 18px}html:not(.js) .js-only{display:none!important}.empty-feed{padding:30px;border:1px dashed var(--line);border-radius:12px;color:var(--muted)}
@media(min-width:1600px){.shell{width:min(1400px,calc(100% - 64px))}.page-layout{grid-template-columns:minmax(0,1fr) 320px;gap:48px}}
