.latest-rail .rail-stories{grid-template-columns:minmax(0,1fr)}.latest-rail .rail-stories .story{grid-template-columns:75px minmax(0,1fr)}body[data-view=home] .page-layout{padding-top:14px}.section-heading h1,.section-heading h2{font-size:21px}.fixture-center.compact{margin-top:12px}.fixture-center.compact .fixture-head{padding:11px 12px;min-height:48px}.fixture-center.compact .fixture-head h2{font-size:17px}.fixture-center.compact .fixture-head .button{font-size:10px;min-height:32px;padding:4px 8px}.fixture-center.compact .fixture-tabs{padding:0 10px 10px;gap:6px}.fixture-center.compact .fixture-tabs button{min-width:72px;font-size:11px;min-height:34px;padding:6px 10px}.fixture-center.compact .fixture-list{display:flex;overflow-x:auto;scroll-snap-type:x proximity;padding:0 10px 10px;gap:9px}.fixture-center.compact .fixture-row{flex:0 0 86%;scroll-snap-align:start;grid-template-columns:minmax(0,1fr) 66px minmax(0,1fr);padding:10px;gap:10px 5px}.fixture-center.compact .fixture-team,.fixture-center.compact .fixture-team.away{flex-direction:column;gap:7px;font-size:12px}.fixture-center.compact .fixture-team img{width:31px;height:31px}.fixture-center.compact .fixture-empty{flex:1;min-width:100%}.fixture-center.compact .fixture-bottom{padding:5px 11px 9px;align-items:flex-start;font-size:9px}.fixture-mini-league{font-size:11px}.fixture-center.compact .fixture-status{font-size:10px}.social-links .widget{padding:15px}.sidebar .widget{padding:18px}.top-ticker .breaking-label{font-size:9px;padding-inline:6px;gap:4px}.top-ticker .breaking-headlines{font-size:10px}}
