.configuration{display:none}body#layout .configuration,body#layout .ad-staging{display:block!important}body#layout .page-layout{display:block}body#layout .sidebar{display:block}body#layout .site-header{position:static}body#layout .primary-nav{position:static;visibility:visible;transform:none}

body.script:
/* ARABIA PRO X 2026. No private credentials belong in this file or its config. */
(() => {
  'use strict';
  const $ = (s, root = document) => root.querySelector(s);
  const $$ = (s, root = document) => [...root.querySelectorAll(s)];
  const storage = { get(k) { try { return localStorage.getItem('arx:' + k); } catch { return null; } },
    set(k, v) { try { localStorage.setItem('arx:' + k, v); } catch { /* Storage is optional. */ } } };
  const parse = (text, fallback) => { try { return JSON.parse(text); } catch { return fallback; } };
  const config = parse($('#arx-config')?.textContent || '{}', {});
  // Empty optional Layout gadgets must not leave decorative blank boxes.
  $$('.sidebar .widget').forEach(widget => {
    const content = $('.widget-content', widget);
    if (content && !content.textContent.trim() && !content.querySelector('img,iframe,video,input,button,a')) widget.hidden = true;
  });
  const node = (tag, cls, text) => { const el = document.createElement(tag); if (cls) el.className = cls;
    if (text !== undefined) el.textContent = text; return el; };
  const safeURL = (value, sameOrigin = false) => {
    if (!value || typeof value !== 'string') return '';
    try { const url = new URL(value, location.href);
      if (!['https:', 'http:'].includes(url.protocol) || (location.protocol === 'https:' && url.protocol !== 'https:')) return '';
      if (sameOrigin && url.origin !== location.origin) return ''; return url.href;
    } catch { return ''; }
  };
  const home = new URL($('link[rel=home]')?.href || '/', location.origin);
  const footerDescription=$('[data-site-description]');if(footerDescription)footerDescription.textContent=$('.masthead .brand-caption')?.textContent.trim()||'';
  // Keep native post HTML intact while opening the homepage to a full-width lead grid.
  const featured=$('[data-home-featured]'), featuredSlot=$('[data-home-feature-slot]');
  if(featured && featuredSlot)featuredSlot.append(featured);
  if(featured && !$('.story',featured)){featured.hidden=true;if(featuredSlot)featuredSlot.hidden=true;}
  const updateClock=()=>{
    const now=new Date(),date=$('[data-top-date]'),time=$('[data-top-time]');
    if(date)date.textContent=new Intl.DateTimeFormat('ar-MA',{weekday:'long',day:'numeric',month:'long',year:'numeric'}).format(now);
    if(time){time.textContent=new Intl.DateTimeFormat('ar-MA',{hour:'2-digit',minute:'2-digit',hour12:false}).format(now);time.dateTime=now.toISOString();}
  };updateClock();setInterval(updateClock,60000);
  $$('.social-links .widget').forEach(widget=>{if(!$$('a',widget).length)widget.hidden=true;});
  const topSocial=$('[data-top-social]');
  if(topSocial)$$('.social-list a').slice(0,6).forEach(link=>{const copy=link.cloneNode(true);$('span',copy)?.remove();topSocial.append(copy);});
  const newsCards=$$('body[data-view=home] .editorial-grid > .story'),filterBar=$('[data-news-filter-bar]');
  if(filterBar && newsCards.length){
    const labels=[...new Set(newsCards.map(card=>$('.pill',card)?.textContent.trim()).filter(Boolean))];
    ['الكل',...labels].forEach((label,index)=>{const button=node('button','news-filter',label);button.type='button';button.setAttribute('aria-pressed',String(index===0));
      button.addEventListener('click',()=>{$$('button',filterBar).forEach(b=>b.setAttribute('aria-pressed',String(b===button)));newsCards.forEach(card=>{card.hidden=index!==0&&$('.pill',card)?.textContent.trim()!==label;});});filterBar.append(button);});
    filterBar.hidden=false;
  }
  const toast = (message) => { const target = $('#arx-toast'); if (!target) return;
    target.textContent = message; target.hidden = false; clearTimeout(toast.timer);
    toast.timer = setTimeout(() => { target.hidden = true; }, 3500); };
  const readBookmarks = () => {
    const value=parse(storage.get('bookmarks') || '[]',[]);
    return Array.isArray(value)?value.filter(item=>item && typeof item.title==='string' && safeURL(item.url,true)).slice(0,50):[];
  };
  function showBookmarks() {
    const dialog=$('#bookmarks-dialog'), list=$('[data-bookmarks-list]',dialog); if(!dialog || !list)return;
    list.replaceChildren(); const saved=readBookmarks();
    if(!saved.length) list.append(node('p','status-message','لم تحفظ أي مقالات بعد على هذا المتصفح.'));
    saved.forEach(item=>{const row=node('div','bookmark-row'),link=node('a','',item.title);link.href=safeURL(item.url,true);link.dir='auto';
      const remove=node('button','button','إزالة');remove.type='button';remove.setAttribute('aria-label','إزالة '+item.title);
      remove.addEventListener('click',()=>{storage.set('bookmarks',JSON.stringify(readBookmarks().filter(v=>v.url!==item.url)));document.dispatchEvent(new Event('arx:bookmarks-changed'));showBookmarks();});row.append(link,remove);list.append(row);});
    if(!dialog.open)dialog.showModal();
  }
  $$('[data-bookmarks-open]').forEach(button=>button.addEventListener('click',showBookmarks));

  // Persisted preference remains optional; the head bootstrap prevents a light flash.
  const themeButton = $('[data-theme-toggle]');
  const modes = ['system', 'light', 'dark'];
  const modeNames = {system: 'النظام', light: 'الفاتح', dark: 'الداكن'};
  const updateThemeLabel = () => {
    if (!themeButton) return;
    const selected = document.documentElement.dataset.theme || 'system';
    themeButton.setAttribute('aria-label', 'المظهر: ' + modeNames[selected] + '؛ اضغط للتبديل');
    themeButton.title = themeButton.getAttribute('aria-label');
  };
  themeButton?.addEventListener('click', () => {
    const current = document.documentElement.dataset.theme || 'system';
    const next = modes[(modes.indexOf(current) + 1) % modes.length];
    document.documentElement.dataset.theme = next; storage.set('theme', next); updateThemeLabel();
  }); updateThemeLabel();

  const menuButton = $('[data-menu-toggle]'), nav = $('#primary-navigation'), backdrop = $('#drawer-backdrop');
  const mobileCategories=$('[data-mobile-categories]');
  if(mobileCategories){const homeLink=$('#primary-navigation a');if(homeLink)mobileCategories.append(homeLink.cloneNode(true));$$('.category-nav-links a').forEach(link=>mobileCategories.append(link.cloneNode(true)));}
  const smallScreen = matchMedia('(max-width:860px)');
  const setMenu = (open, focus = false) => {
    if (!nav || !menuButton) return;
    document.documentElement.style.setProperty('--drawer-top',Math.max(0,$('.site-header').getBoundingClientRect().bottom)+'px');
    nav.classList.toggle('open', open); backdrop?.classList.toggle('open', open);
    menuButton.setAttribute('aria-expanded', String(open));
    menuButton.setAttribute('aria-label', open ? 'إغلاق القائمة' : 'فتح القائمة');
    nav.inert = smallScreen.matches && !open;
    document.body.classList.toggle('scroll-lock', open && smallScreen.matches);
    if (focus) (open ? $('a,button', nav) : menuButton)?.focus();
  };
  menuButton?.addEventListener('click', () => setMenu(!nav.classList.contains('open'), true));
  backdrop?.addEventListener('click', () => setMenu(false, true));
  smallScreen.addEventListener('change', () => setMenu(false)); setMenu(false);
  document.addEventListener('keydown', (event) => {
    if (event.key === 'Escape') { if (nav?.classList.contains('open')) setMenu(false, true);
      $$('.explore[open]').forEach(el => { el.open = false; $('summary', el)?.focus(); }); }
    if (event.key === 'Tab' && smallScreen.matches && nav?.classList.contains('open')) {
      const links = [menuButton, ...$$('a,button,summary', nav)].filter(el => !el.hidden);
      const first = links[0], last = links[links.length - 1];
      if (event.shiftKey && document.activeElement === first) { last.focus(); event.preventDefault(); }
      else if (!event.shiftKey && document.activeElement === last) { first.focus(); event.preventDefault(); }
    }
  });
  document.addEventListener('click', event => { $$('.explore[open]').forEach(el => { if (!el.contains(event.target)) el.open = false; }); });
  $$('.primary-nav a').forEach(a => { if (a.href === location.href) a.setAttribute('aria-current', 'page'); });
  const search = $('#search-dialog');
  $('[data-search-open]')?.addEventListener('click', () => { setMenu(false); search?.showModal(); $('input', search)?.focus(); });
  $$('[data-dialog-close]').forEach(button => button.addEventListener('click', () => button.closest('dialog')?.close()));
  $$('dialog').forEach(dialog => dialog.addEventListener('click', event => { if (event.target === dialog) {
    const r = dialog.getBoundingClientRect(); if (event.clientX < r.left || event.clientX > r.right || event.clientY < r.top || event.clientY > r.bottom) dialog.close();
  } }));

  // Real Blogger feeds, with bounded requests and no JSONP execution.
  const feedRequests = new Map();
  async function feed(label, count = 6, order = '') {
    const url = new URL('feeds/posts/summary' + (label ? '/-/' + encodeURIComponent(label) : ''), home);
    url.searchParams.set('alt', 'json'); url.searchParams.set('max-results', Math.min(12, count));
    if (order) url.searchParams.set('orderby', order);
    if (!feedRequests.has(url.href)) feedRequests.set(url.href, (async () => {
      const response = await fetch(url, {signal: AbortSignal.timeout(10000), credentials: 'same-origin'});
      if (!response.ok) throw new Error('feed-unavailable');
      const payload = await response.json();
      if (!payload.feed) throw new Error('feed-invalid');
      return (payload.feed.entry || []).map(entry => {
        const link = entry.link?.find(item => item.rel === 'alternate');
        const parsed = new DOMParser().parseFromString(entry.summary?.$t || '', 'text/html');
        return {title: entry.title?.$t || '', url: safeURL(link?.href || '', true),
          image: safeURL(entry.media$thumbnail?.url || ''), date: entry.published?.$t || '',
          author: entry.author?.[0]?.name?.$t || '', summary: (parsed.body.textContent || '').trim().slice(0, 160)};
      }).filter(post => post.url && post.title);
    })());
    return feedRequests.get(url.href);
  }
  function storyCard(post) {
    const article = node('article', 'story'), media = node('a', 'story-media'); media.href = post.url; media.tabIndex = -1; media.setAttribute('aria-hidden', 'true');
    if (post.image) { const image = node('img'); image.src = post.image; image.alt = ''; image.loading = 'lazy'; image.decoding = 'async'; image.width = 480; image.height = 300; media.append(image); }
    else { media.classList.add('no-image'); media.textContent = 'مقال'; }
    const copy = node('div', 'story-copy'), heading = node('h3'), link = node('a', '', post.title);
    link.href = post.url; link.dir = 'auto'; heading.append(link); copy.append(heading);
    const date = new Date(post.date); if (Number.isFinite(date.getTime())) { const time = node('time', 'story-meta', new Intl.DateTimeFormat('ar', {dateStyle:'medium'}).format(date)); time.dateTime = date.toISOString(); copy.append(time); }
    article.append(media, copy); return article;
  }
  const observedModules = new WeakMap();
  const lazy = 'IntersectionObserver' in window ? new IntersectionObserver(entries => entries.forEach(entry => {
    if (entry.isIntersecting) { lazy.unobserve(entry.target); (observedModules.get(entry.target) || []).forEach(loadModule); }
  }), {rootMargin:'500px'}) : null;
  async function loadModule(module) {
    const label = module.dataset.label || ''; if (!label && !module.hasAttribute('data-related')) return;
    try {
      let posts = await feed(label, Number(module.dataset.count) || 6);
      if (module.hasAttribute('data-related')) posts = posts.filter(post => new URL(post.url).pathname !== location.pathname).slice(0, 3);
      if (!posts.length) return;
      const head = node('div', 'section-heading'), heading = node('h2', '', module.dataset.title || label || 'اقرأ أيضًا'); head.append(heading);
      if (!module.hasAttribute('data-related')) { const all = node('a', '', 'كل المقالات ←'); all.href = new URL('search/label/' + encodeURIComponent(label), home).href; head.append(all); }
      const grid = node('div', 'module-grid'); posts.forEach(post => grid.append(storyCard(post)));
      module.replaceChildren(head, grid); module.classList.add('module'); module.hidden = false;
    } catch { /* Native articles remain available when a feed is unavailable. */ }
  }
  $$('[data-arx-module], [data-related]').forEach(module => { if (lazy) { const target=module.parentElement; const list=observedModules.get(target) || []; list.push(module); observedModules.set(target,list); lazy.observe(target); } else loadModule(module); });
  $$('[data-arx-breaking]').forEach(async root => {
    try { const posts = await feed(root.dataset.label || '', 5); if (!posts.length) return;
      root.replaceChildren(node('span','breaking-label', root.dataset.title || 'في الواجهة'));
      const links = node('div','breaking-headlines'); posts.forEach((post,index) => { const a = node('a','',post.title); a.href = post.url; a.dir = 'auto'; a.hidden=index!==0;links.append(a); });
      const controls=node('div','ticker-controls');let current=0;
